INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass die Rentabilität einer Investition immer in Prozent angegeben wird?', 2, '[{"text": "Ja", "correct": true, "because": "Prozent ist Standard für ROI"}, {"text": "Nein", "correct": false, "because": "Prozent ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie berechne ich die Rendite einer Investition?', 3, '[{"text": "(Gewinn - Kosten) / Kosten", "correct": true, "because": "Formel für ROI"}, {"text": "Gewinn + Kosten", "correct": false, "because": "Falsche Berechnung"}, {"text": "Kosten / Gewinn", "correct": false, "because": "Umgedrehte Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Rentabilität einer Investition?', 5, '[{"text": "Investitionskosten", "correct": true, "because": "Bestimmen Basis"}, {"text": "Erzielter Gewinn", "correct": true, "because": "Kern der Rendite"}, {"text": "Firmenlogo", "correct": false, "because": "Kein finanzieller Faktor"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant für Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine hohe Rendite zeigt gute Investition. b) Sie berücksichtigt immer die Zeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Zeit nicht direkt einbezogen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Berechnung einer Investitionsrendite?', 4, '[{"text": "Kosten", "correct": false, "because": "Kern der Formel"}, {"text": "Erlöse", "correct": false, "because": "Bestimmen Gewinn"}, {"text": "Marketingfarben", "correct": true, "because": "Kein finanzieller Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Rendite immer positiv sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Verluste führen zu negativem ROI"}, {"text": "Ja", "correct": false, "because": "Negative Werte möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kennzahl vergleicht Gewinn mit Investitionskosten?', 3, '[{"text": "ROI", "correct": true, "because": "Misst Rentabilität"}, {"text": "EBIT", "correct": false, "because": "Misst Betriebsgewinn"}, {"text": "Umsatz", "correct": false, "because": "Keine Rentabilitätskennzahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Rendite immer langfristige Kosten einbezieht. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Hängt von Berechnungszeitraum ab"}, {"text": "Ja", "correct": false, "because": "Flexibel einstellbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Rendite dasselbe wie der Gewinn?', 2, '[{"text": "Nein", "correct": true, "because": "ROI ist relative Kennzahl"}, {"text": "Ja", "correct": false, "because": "Gewinn ist absoluter Wert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten berücksichtige ich bei einer Investitionsanalyse?', 4, '[{"text": "Anschaffungskosten", "correct": true, "because": "Direkte Investition"}, {"text": "Betriebskosten", "correct": true, "because": "Laufende Ausgaben"}, {"text": "Reisekosten", "correct": false, "because": "Nur kontextabhängig"}, {"text": "Kaffeespesen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Bewertung einer Investition?', 4, '[{"text": "Genaue Kostenerfassung", "correct": true, "because": "Sichert präzise Berechnung"}, {"text": "Schnelle Analyse", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Schöne Diagramme", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ROI misst Gewinn relativ zu Kosten. b) Es berücksichtigt Inflation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Inflation separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Berechnung einer Rendite?', 3, '[{"text": "Gewinn", "correct": false, "because": "Kern der Formel"}, {"text": "Investitionskosten", "correct": false, "because": "Basis der Berechnung"}, {"text": "Firmenfarben", "correct": true, "because": "Kein finanzieller Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Rendite eines Projekts berechne?', 4, '[{"text": "Gewinn minus Kosten, geteilt durch Kosten", "correct": true, "because": "Korrekte Formel"}, {"text": "Nur Gewinn zählen", "correct": false, "because": "Fehlt Kostenbasis"}, {"text": "Kosten verdoppeln", "correct": false, "because": "Falsche Logik"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Rendite alle Risiken einbezieht. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Risiken separat analysiert"}, {"text": "Ja", "correct": false, "because": "ROI fokussiert Gewinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, Investitionen zu vergleichen?', 4, '[{"text": "Vergleichbare ROI-Berechnung", "correct": true, "because": "Einheitliche Kennzahl"}, {"text": "Zufällige Schätzung", "correct": false, "because": "Unzuverlässig"}, {"text": "Höhere Kosten", "correct": false, "because": "Kein Vergleichsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein negativer Wert möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Verluste führen dazu"}, {"text": "Nein", "correct": false, "because": "Negative Werte erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Berechnung einer Rendite?', 5, '[{"text": "Vergleichbarkeit", "correct": true, "because": "Einheitliche Kennzahl"}, {"text": "Entscheidungsgrundlage", "correct": true, "because": "Zeigt Rentabilität"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Visuals", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Investitionsbewertung unwichtig?', 3, '[{"text": "Kostengenauigkeit", "correct": false, "because": "Sichert Präzision"}, {"text": "Gewinnerwartung", "correct": false, "because": "Kern der Analyse"}, {"text": "Präsentationsdesign", "correct": true, "because": "Kein finanzieller Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich die Rentabilität eines Marketingprojekts bewerte?', 4, '[{"text": "Kosten und generierten Umsatz vergleichen", "correct": true, "because": "Liefert ROI"}, {"text": "Nur Umsatz zählen", "correct": false, "because": "Fehlt Kostenbasis"}, {"text": "Teamgröße messen", "correct": false, "because": "Irrelevant"}]');
